import { JSX } from 'react';

import { Canvas } from '@storybook/addon-docs/blocks';
import { createUrl } from 'playroom/utils';
import ts from 'typescript';

const convertReactHooks = (code: string): string => {
  const reactHooks = [
    'useId',
    'useState',
    'useEffect',
    'useRef',
    'useContext',
    'useReducer',
    'useCallback',
    'useMemo',
    'useImperativeHandle',
    'useLayoutEffect',
    'useDebugValue',
  ];

  reactHooks.forEach((hook) => {
    code = code.replace(new RegExp(`${hook}\\(`, 'g'), `React.${hook}(`);
  });

  return code;
};

const convertTSXToJSX = (code: string): string => {
  return ts.transpile(code, {
    jsx: ts.JsxEmit.Preserve,
    target: ts.ScriptTarget.ESNext,
  });
};

const processCode = (code: string): string => {
  const jsx = convertTSXToJSX(extractArrowFunctionContent(code));
  let source = convertReactHooks(jsx);

  // remove import statements
  source = source.replace(/import\s+.*?from\s+['"].*?['"];?\s*/g, '');

  // need to remove default export statements like this: export default AlertExample;
  source = source.replace(/^.*export\s+default\s+.*$/gm, '');

  // get name of component if it starts with const ComponentName = () => {}
  const componentName = source.match(
    /const\s+(\w+)\s*=\s*\(\s*\)\s*=>\s*{/
  )?.[1];

  return `{
  (() => {
    ${source}
   ${componentName ? `return <${componentName} />` : ''}
  })()
}`;
};

function extractArrowFunctionContent(str: string): string {
  const regex =
    /render:\s*((\(_args\)|\(args\))\s*:\s*JSX\.Element\s*=>\s*{|function\s+Render\((_args|args)\):\s*JSX\.Element\s*{)/;
  const match = str.match(regex);
  if (!match) return str;

  const startIndex = (match.index ?? 0) + match[0].length;
  let openBraces = 1;
  let endIndex = startIndex;

  while (openBraces > 0 && endIndex < str.length) {
    if (str[endIndex] === '{') {
      openBraces++;
    } else if (str[endIndex] === '}') {
      openBraces--;
    }
    endIndex++;
  }
  return str.slice(startIndex, endIndex - 1).trim();
}

const getPlayroomUrlFromSource = (code: string): string => {
  let baseUrl = '';

  if (process.env.NODE_ENV === 'development') {
    baseUrl = 'http://localhost:9000';
  } else {
    // Get the current URL's origin and pathname
    const { origin, pathname } = window.location;

    // Extract the base path up to the last directory that contains the current application
    // This assumes that "/playroom/index.html" should be a sibling to the current application path
    const basePath = pathname.split('/').slice(0, -1).join('/');

    // Construct the full playroom URL
    baseUrl = `${origin}${basePath}/playroom/index.html`;
  }

  let url = createUrl({
    baseUrl,
    code,
    title: 'Playroom',
    paramType: 'search',
  });

  url = url.replace('index.html/', 'index.html');
  return url;
};

export const PlayroomCanvas: typeof Canvas = ({ of }): JSX.Element => {
  return (
    <Canvas
      of={of}
      additionalActions={[
        {
          title: 'Open in Playroom',
          onClick: (): void => {
            const sourceCode =
              of.parameters.docs.source.code ??
              of.parameters.docs.source.originalSource;
            const code = processCode(sourceCode);

            const url = getPlayroomUrlFromSource(code);
            window.open(url, '_blank');
          },
        },
      ]}
    />
  );
};
